//! Replays reminders_ts_vectors.json (outcomes of the real flag-off
//! scheduleSavedEmbedReminders, regenerated by workReminderVectors.test.ts) through the Rust op.
use serde_json::{Value, json};

use super::run_json;

fn vectors() -> Value {
    expand(serde_json::from_str(include_str!("reminders_ts_vectors.json")).expect("vectors parse"))
}

/// Undoes the vitest `compact`: `{"$repeat": [char, count, head?]}` is `head + char × count`.
fn expand(value: Value) -> Value {
    match value {
        Value::Object(map) if map.len() == 1 && map.contains_key("$repeat") => {
            let spec = map["$repeat"].as_array().expect("repeat spec");
            let unit = spec[0].as_str().expect("repeat char");
            let count = usize::try_from(spec[1].as_u64().expect("repeat count")).expect("count fits");
            let head = spec.get(2).map_or("", |h| h.as_str().expect("repeat head"));
            Value::String(format!("{head}{}", unit.repeat(count)))
        }
        Value::Object(map) => Value::Object(map.into_iter().map(|(k, v)| (k, expand(v))).collect()),
        Value::Array(items) => Value::Array(items.into_iter().map(expand).collect()),
        other => other,
    }
}

fn run(input: &Value, name: &Value) -> Value {
    let output = run_json("reminderSavedSchedule", &input.to_string()).unwrap_or_else(|e| panic!("{name}: {e}"));
    serde_json::from_str(&output).expect("output json")
}

/// The ordered body `[[name, value], ...]` the page builds from the steps;
/// `trigger` fills `trigger_datetime`, the expected body the other page slots.
fn body(request: &Value, trigger: &Value, expected: &Value) -> Value {
    let slot = |name: &str| {
        let entry = expected.as_array().expect("body entries").iter().find(|e| e[0] == name);
        entry.map_or(Value::Null, |e| e[1].clone())
    };
    let steps = request["steps"].as_array().expect("steps");
    Value::Array(
        steps
            .iter()
            .map(|step| {
                let name = step[0].as_str().expect("step name");
                let value = match step[1].get("value") {
                    Some(value) => value.clone(),
                    None if step[1]["slot"] == "trigger_datetime" => trigger.clone(),
                    None => slot(step[1]["slot"].as_str().expect("slot")),
                };
                json!([name, value])
            })
            .collect(),
    )
}

#[test]
fn saved_item_schedules_equal_typescript() {
    let doc = vectors();
    let cases = doc["cases"].as_array().expect("cases");
    assert!(cases.len() >= 25, "every reminder case is recorded");
    for case in cases {
        let name = &case["name"];
        let out = run(&case["input"], name);
        let expected = &case["expected"];
        if expected["schedule"].is_null() {
            assert_eq!(out, json!({ "schedule": null }), "{name}");
            continue;
        }
        let (got, want) = (&out["schedule"], &expected["schedule"]);
        for key in ["title", "promptTitle", "sourceChatId", "thumbnailUrl", "context", "triggers"] {
            assert_eq!(got.get(key), want.get(key), "{name}: {key}");
        }
        assert_eq!(got["request"]["path"], want["path"], "{name}: path");
        assert_eq!(got["request"]["method"], want["method"], "{name}: method");
        let bodies = want["bodies"].as_array().expect("bodies");
        assert_eq!(bodies.len(), want["triggers"].as_array().expect("triggers").len(), "{name}: one POST per trigger");
        for (index, expected_body) in bodies.iter().enumerate() {
            let trigger = &want["triggers"][index];
            assert_eq!(body(&got["request"], trigger, expected_body), *expected_body, "{name}: body {index}");
        }
    }
}

#[test]
fn malformed_reminder_inputs_are_refused() {
    assert_eq!(run_json("reminderNothing", "{}").unwrap_err(), "unknown_op:reminderNothing");
    let no_dates = json!({ "kind": "event", "content": { "date_start": "2027-01-01" }, "dates": {} });
    assert_eq!(
        run_json("reminderSavedSchedule", &no_dates.to_string()).unwrap_err(),
        "missing_field:dates.2027-01-01"
    );
    let no_slot = json!({ "kind": "health_appointment", "content": { "slot_datetime": "x" }, "dates": { "x": null } });
    assert_eq!(run_json("reminderSavedSchedule", &no_slot.to_string()).unwrap_err(), "missing_field:slotLabel");
    let no_content = json!({ "kind": "event", "dates": {} });
    assert_eq!(run_json("reminderSavedSchedule", &no_content.to_string()).unwrap_err(), "missing_field:content");
}
